loggingModel.recordStartTime();

const consoleWarn = console.warn.bind(console);
console.warn = (...data: unknown[]) => {
    if (environment === 'live') {
        return;
    }

    consoleWarn(data);
};

const consoleError = console.error.bind(console);
// eslint-disable-next-line @typescript-eslint/no-explicit-any
console.error = (message?: any, ...optionalParams: unknown[]) => {
    if (environment === 'live' || environment === 'stage') {
        try {
            loggingModel.logException(message);
        } catch (logError) {
            consoleError(logError);
        }
    } else {
        loggingModel.trackError(message.stack);
    }
    consoleError(message, optionalParams);
};

export class BaseGame {
    private isRunning = false;
    public static isLazyLoadComplete: boolean = false;
    public static isLazyInitComplete: boolean = false;
    public static gameNameMap: Record<string, string> = {};

    public async initialise(config: IEngineConfig, gameBindings: ContainerModule, regionBindings?: ContainerModule): Promise<void> {
        Vue.config.productionTip = false;

        gameConfig.apply(config);
        DeviceEx.initialise();

        await inversifyContainer.initialise(gameBindings, regionBindings);
        userPreferences.initialiseGamePreferences();

        await Bootstrap.initAuth();

        const gameConfigResponse = await inversifyContainer.gameConfigProvider.fetch();

        let launcher: IGameConfig | undefined;
        if (gameConfigResponse) {
            launcher = gameConfigResponse.launchers.find((l) => l.name.toLowerCase() === queryStringParams.currentSkin);
            gameConfigResponse?.launchers.forEach(launcher => {
                BaseGame.gameNameMap[launcher.name.toLowerCase()] = launcher.displayName;
            });

            // TEMP: allow forcing TealTheme for easy Arcade 2.0 roll out / roll back
            const settingsLauncher = gameConfigResponse.launchers.find(l => l.name.toLowerCase() === 'settings');
            const forceTealTheme = parseBool(settingsLauncher?.settings.forceTealTheme ?? 'false');

            if (forceTealTheme) {
                inversifyContainer.operatorModel.forceTombolaOperator();
            }
        }

        const baseTheme = inversifyContainer.operatorModel.baseTheme;

        const splashData = {
            bgColour: launcher?.backgroundColour ?? baseTheme.midAccent.string,
            image: launcher?.imageUrls.splash ?? 'undefined'
        };
        Vue.use(SettingsPlugin, { userId: userModel.userId, gameName: queryStringParams.currentSkin, theme: baseTheme });
        Vue.use(OverlaysPlugin, { logoBase64: splashData.image, theme: baseTheme, splashBackgroundColour: splashData.bgColour });
        if (config.VuePlugin) {
            Vue.use(config.VuePlugin);
        }

        new Vue({
            el: '#app',
            render: (h) => h(AppRootComponent)
        });

        // treating undefined as true to allow backwards compat with current games
        if (config.AutoRun === undefined || config.AutoRun === true) {
            this.run();
        }
    }

    public async run(): Promise<void> {
        if (this.isRunning) { return; }

        this.isRunning = true;
        Bootstrap.run();
    }
}
